def evidence(code):
 key=TRIAL_FOR[code];e=copy.deepcopy(TRIALS[key]);src=e['sources']
 if key=='crystal':
  e['endpoints']=[endpoint('OS','Median overall survival','28.4 versus 20.2 months; HR 0.69 (95% CI 0.54–0.88); P=.0024.','Group survival medians; not an individual prediction.',src),endpoint('PFS','Median progression-free survival','11.4 versus 8.4 months; HR 0.56 (95% CI 0.41–0.76); P=.0002.','Time to progression or death; distinct from overall survival.',src),endpoint('ORR','Objective response','66.3% versus 38.6%; odds ratio 3.11 (95% CI 2.03–4.78).','Tumour response, not cure.',src)]
  e['applicability']='Direct weekly-cetuximab/FOLFIRI combination evidence in the first-line trial setting.' if code=='00328' else 'Indirect schedule evidence: CRYSTAL used weekly cetuximab; NCCP 00585 uses cetuximab every 14 days. The current SmPC permits fortnightly dosing, but these are not separately randomized 00585 survival estimates.'
 elif key=='epic':
  e['endpoints']=[endpoint('OS','Median overall survival','12.3 versus 12.0 months; HR 0.91 (95% CI 0.71–1.17); P=.4645.','No statistically significant overall-survival difference.',src),endpoint('PFS','Median progression-free survival','5.4 versus 2.6 months; HR 0.57 (95% CI 0.46–0.69); P<.0001.','Improved disease control in the trial subgroup.',src),endpoint('ORR','Objective response','29.4% versus 5.0%.','More tumour responses, not a demonstrated survival gain.',src)]
  e['applicability']='Indirect schedule evidence: EPIC used irinotecan every three weeks; this NCCP regimen uses 180 mg/m² every 14 days.'+(' EPIC also used weekly rather than fortnightly cetuximab.' if code=='00331' else ' The cetuximab schedule is weekly in both.')
 elif key=='opus':
  e['endpoints']=[endpoint('ORR','Objective response','58% versus 29%; odds ratio 3.33 (95% CI 1.36–8.17); P=.0084.','Improved response in the exploratory RAS-wild-type group.',src),endpoint('PFS','Median progression-free survival','12.0 versus 5.8 months; HR 0.53 (95% CI 0.27–1.04); P=.0615.','Not statistically significant; confidence interval includes no difference.',src),endpoint('OS','Median overall survival','19.8 versus 17.8 months; HR 0.94 (95% CI 0.56–1.56); P=.80.','No demonstrated overall-survival difference.',src)]
  e['applicability']='Direct regimen-family evidence for weekly cetuximab with FOLFOX4, in the first-line trial population.' if code=='00692' else 'Indirect for both schedule and backbone: OPUS used weekly cetuximab with FOLFOX4, not fortnightly cetuximab with modified FOLFOX6. Do not relabel OPUS results as an exact 00733 trial.'
 elif key=='co17':
  e['endpoints']=[endpoint('OS','Median overall survival','9.5 versus 4.8 months; HR 0.55 (95% CI 0.41–0.74); P<.001.','Group medians in the older KRAS-defined population.',src),endpoint('PFS','Median progression-free survival','3.7 versus 1.9 months; HR 0.40 (95% CI 0.30–0.54); P<.001.','Disease control improved; this is not a personal life expectancy.',src)]
  e['applicability']='Indirect schedule evidence: CO.17 administered cetuximab weekly; NCCP 00732 is fortnightly. Modern prescribing requires validated extended RAS wild-type status.'
 elif key=='pani':
  e['endpoints']=[endpoint('OS','Median overall survival: extended RAS-wild-type secondary analysis','10.0 versus 6.9 months; HR 0.70 (95% CI 0.53–0.93); P=.0135.','Secondary biomarker-defined result, with the same antibody dose and interval as NCCP 00225.',src,status='Published randomized trial; secondary extended-RAS analysis')]
  e['applicability']='Direct schedule and later-line monotherapy evidence; extended RAS subgroup qualification must remain visible. The primary KRAS exon 2 result had a different control median (7.4 months).'
 else:
  e['endpoints']=[endpoint('OS','One-year overall survival','36.2% versus 13.8%; overall survival comparison P=.0001.','A fixed-time survival proportion, not median survival or a present-day personalized estimate.',src,status='Published randomized historical trial')]
  e['applicability']='Relevant three-weekly single-agent evidence after fluorouracil failure. It does not quantify benefit over modern alternative regimens.'
 e['checked']=DATE
 return e

