def row(label,cells):return dict(label=label,cells=cells)
def monitoring(c):
 rows=[row('Blood counts, kidney and liver',['Baseline blood count, kidney and liver profile','Review results before treatment', 'Weekly blood count; kidney and liver tests before each cycle' if c=='00213' else ('Blood count, kidney and liver tests before each treatment' if c=='00225' else 'Regular blood tests; confirm the schedule with your team'), 'Repeat sooner if symptoms or results need it','Follow any unresolved abnormal result'])]
 if c in PUMP:rows[0]['cells'][2]='Blood count, kidney and liver tests before each cycle'
 if c in EGFR:
  rows.append(row('Magnesium, calcium and potassium',['Check mineral levels before starting','Repeat periodically during treatment','Keep blood-test and replacement appointments','More checks may be needed if levels fall or diarrhoea develops','Monthly checks for two months after the last antibody dose']))
  rows.append(row('Skin, nails, eyes and breathing',['Discuss existing skin, eye or lung problems','Start the prescribed skin-care plan; report reactions early','Review skin, nails, diarrhoea and new symptoms','Eye pain, worsening breathing or severe rash needs prompt assessment','Continue care until symptoms and mineral levels settle']))
 if c in IRINO:
  rows.append(row('Bowel symptoms and hydration',['Have a written diarrhoea plan and emergency contact','Tell the nurse about cramps, sweating or diarrhoea during infusion','Delayed diarrhoea can start after the first day; act using your written plan','Fever, reduced urine, severe pain or inability to drink needs urgent advice','Restart decisions require recovery and team review']))
 if c in PUMP:
  rows.append(row('Fluorouracil safety and line',['Confirm the DPD test and safe line/pump arrangements','Check mouth, bowel and pump symptoms early','Review line, pump and previous-cycle toxicity','Report chest pain or unexpectedly severe early side effects immediately','Confirm disconnection and ongoing line care']))
 if c in FOLFOX:
  rows.append(row('Nerve symptoms',['Record any numbness or tingling before treatment','Cold sensitivity can occur early','Formal neuropathy assessment every two cycles','Report persistent symptoms or difficulty with daily tasks before the next dose','Follow symptoms after oxaliplatin stops']))
 rows.append(row('Cancer response and treatment choices',['Record baseline disease and agree review plan','Bring forward review if symptoms worsen','Scans and other tests follow your consultant’s treatment plan','Discuss benefit, side effects and whether the goal has changed','Agree continuation, a break, another treatment or supportive care']))
 return dict(title='When checks happen',columns=['Before starting','Early treatment','Repeated treatment','Longer-term review','Pause / completion'],rows=rows,note='The columns show order, not equal periods. There is no fixed number of cycles for these plans. Agree who books each check, when results are reviewed and whom to contact if a check is missed.',source_ids=['nccp']+(['smpc'] if c in EGFR else []))

