def clinical(c,p,e):
 chemo=c not in {'00225','00732'};cetux=c in EGFR-{'00225'}
 summary=('EGFR blockade is combined with the '+('irinotecan/fluorouracil/folinic-acid FOLFIRI backbone' if c in FOLFIRI else 'oxaliplatin/fluorouracil/folinic-acid FOLFOX backbone' if c in FOLFOX else 'topoisomerase-I inhibitor irinotecan')+' to control selected metastatic colorectal cancer.' if cetux and chemo else 'EGFR-antibody monotherapy offers a molecularly selected later-line option for metastatic colorectal cancer.' if c in EGFR else 'Single-agent irinotecan provides a topoisomerase-I inhibitor option after fluorouracil-based treatment failure in advanced colorectal cancer.')
 baseline=['Confirm diagnosis, treatment line, goal, prior treatments, performance status, consent and all medicines.','Baseline FBC, renal and liver profile; assess infection, hydration, bowel symptoms and previous treatment toxicity.']
 if c in EGFR:baseline+=['Document validated extended RAS wild-type status for this colorectal pathway; do not infer it from unknown or KRAS exon 2-only testing.','Measure electrolytes including magnesium, calcium and potassium before treatment; correct abnormalities according to the prescription.']
 if cetux:baseline+=['Ask specifically about prior antibody infusion reactions, red-meat allergy, tick bites and any known cetuximab IgE findings.']
 if c in PUMP:baseline+=['Document DPD assessment before the first fluorouracil dose unless already tested. Complete DPD deficiency excludes fluorouracil; partial deficiency needs a specialist dose plan.','ECG if cardiac function is compromised; no universal serial echo schedule is imposed. Confirm safe central access and pump training.']
 if c in {'00328','00585','00733'}:baseline+=['In moderate/severe renal impairment, elevated uracil can misclassify DPD phenotype; consider genotype testing as directed in the current NCCP source.']
 if c in IRINO:baseline+=['Review prior severe diarrhoea, bowel disease/obstruction, bilirubin and known UGT1A1*28 status. A genotype-related starting-dose decision is individualized.']
 if c in FOLFOX:baseline+=['Record baseline peripheral neuropathy and functional impact.']
 before=['Review symptoms, infection, hydration, bowel effects, medicines and previous-cycle toxicity; verify which components are actually being administered.']
 before+=['FBC weekly; renal and liver profile before each 21-day cycle.'] if c=='00213' else ['FBC, liver and renal profile before each treatment.'] if c=='00225' else ['FBC, liver and renal profile before each cycle.'] if c in PUMP else ['FBC, liver and renal profile regularly; the NCCP source does not specify a fixed interval for these tests in this regimen. Agree it locally and repeat when clinically indicated.']
 if c in EGFR:before+=['Repeat magnesium, calcium and potassium periodically during EGFR-antibody therapy and more frequently when abnormal; assess skin, nail, eye and pulmonary symptoms.']
