 risk=dict(level='low' if c in {'00225','00732'} else 'moderate',script_id='nccp-v8-low-v08418' if c in {'00225','00732'} else 'nccp-v8-moderate-v08418',mapping_basis=f'Current NCCP {c} v{S[c]["version"]} active treatment-day classification; separate antibody-only days use low-risk support; NCIS V8 antiemetic guidance.',mapping_confidence='high')
